use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node's `with` clause grants. The host enforces the same
/// allowlist at the crossing; checking here first means an out-of-scope URL
/// becomes a recorded failure instead of a trap that aborts the whole batch.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Bound on how many subscriptions one run will attempt. Anything past this
/// is recorded as a failure rather than fetched.
const MAX_SUBSCRIPTIONS: usize = 256;

struct Node;

/// Returns true only for an https or http URL whose authority host exactly
/// matches an allowlisted host. Anything unusual (userinfo, whitespace,
/// control characters, other schemes) is rejected.
fn allowed_host(url: &str) -> bool {
    if url.bytes().any(|b| b <= b' ' || b == 0x7f) {
        return false;
    }

    let rest = if has_prefix_ci(url, "https://") {
        &url[8..]
    } else if has_prefix_ci(url, "http://") {
        &url[7..]
    } else {
        return false;
    };

    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    if authority.is_empty() || authority.contains('@') {
        return false;
    }

    let host = match authority.rfind(':') {
        Some(i) => &authority[..i],
        None => authority,
    };

    ALLOWED_HOSTS.iter().any(|h| h.eq_ignore_ascii_case(host))
}

fn has_prefix_ci(s: &str, prefix: &str) -> bool {
    s.len() >= prefix.len() && s.as_bytes()[..prefix.len()].eq_ignore_ascii_case(prefix.as_bytes())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for (i, url) in subscriptions.urls.into_iter().enumerate() {
            if i >= MAX_SUBSCRIPTIONS {
                failures.push(FetchFailure {
                    url,
                    error: "too many subscriptions in one run".to_string(),
                });
                continue;
            }

            if !allowed_host(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in node's allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
